//! Shared source inputs; no native answers or expected rows.
pub const CASES:&[&str]=&["basic","macro","retired","exempt","hidden"];
pub fn files(case:&str)->Vec<(&'static str,Vec<u8>)>{let source=if case=="macro"{"#define OLD_CALLBACK req_bool\n/proc/req_bool(value)\n    return value\n/proc/probe()\n    OLD_CALLBACK(1)\n"}else if case=="retired"{"#define REQ_FAKE(X) X\n/proc/req_bool(value)\n    return value\n/proc/probe()\n    var/retired = REQ_FAKE(1)\n    req_bool(retired)\n"}else{"/proc/req_bool(value)\n    return value\n/proc/probe()\n    req_bool(1)\n    var/noise = \"req_bool(ignored)\"\n    // req_bool(ignored)\n"};let scope=if case=="exempt"{"[lint.requirement_bool]\nexempt_files=['code/probe.dm']\n[lint.requirement_bool.lists]\nretired_macros=['REQ_FAKE']\n"}else{"[lint.requirement_bool.lists]\nretired_macros=['REQ_FAKE']\n"};let mut out=vec![("deepquarry.dme",b"#include \"code/probe.dm\"\n".to_vec()),("code/probe.dm",source.as_bytes().to_vec()),("tools/ci/lint_scopes.toml",scope.as_bytes().to_vec())];if case=="hidden"{out.push(("code/.hidden/ignored.dm",b"req_bool(ignored)\nREQ_FAKE(ignored)\n".to_vec()));}out}
